 if(['local-dimming','led-light'].includes(id))return `<div class="experiment optics-experiment"><div class="pixel-grid" aria-hidden="true">${Array.from({length:36},(_,i)=>`<span class="${[8,9,14,15,20,21].includes(i)?'lit':''}"></span>`).join('')}</div><div class="signal-line"><span>Light source</span><i>→</i><span>${state.object==='macbook'?'LCD pixels':'Visible light'}</span></div></div>`;
